  ciphering_algorithms = ( "nea2", "nea1" );

  # preferred integrity algorithms
  # the first one of the list that an UE supports in chosen
  # valid values: nia0, nia1, nia2, nia3
  integrity_algorithms = ( "nia2", "nia1" );

  # setting 'drb_ciphering' to "no" disables ciphering for DRBs, no matter
  # what 'ciphering_algorithms' configures; same thing for 'drb_integrity'
  drb_ciphering = "yes";
  drb_integrity = "no";
};

interface_security = {

  f1c_protection  = "dtls";   # dtls | ipsec | none
  n2_protection   = "ipsec";   # dtls | ipsec | none
  n3_protection   = "ipsec";   # ipsec | none
  xn_protection   = "none";   # dtls | ipsec | none
  e2_protection   = "ipsec";   # ipsec | none
  o1_transport    = "netconf_tls";   # netconf_ssh | netconf_tls | netconf_plain
  tls_min_version = "1.3";   # 1.0 | 1.1 | 1.2 | 1.3
};
